;КузнецZD_SM=-ZD_+PL        DW ZD0+SM,ZD1+SM,ZD2+SM,ZD3+SM,ZD4+SM        DW ZD5+SM,ZD6+SM,ZD7+SM,ZD8+SM,ZD9+SM        DW ZD10+SM,ZD11+SM,ZD12+SM,ZD13+SMZD0     DB "Хочешь, подарю?",SOBES        DB "Чо это вы мне тут суете? У меня",CR        DB "у самого такого добра навалом!",ENDZD1     DB "Ну, вылитый кузнец!",SOBES        DB "Я весь в батю! Он тоже кузнец...",HERO;           123456789-123456789-123456789-123        DB "Хорошая у вас семья!",DIALOG,9ZD2     DB "Здравствуйте, меня зовут Вера.",CR        DB "Я пришла помочь вашей деревне.",SOBES        DB "Моя фамилия Задолбайло. Я кузнец.",CR        DB "Кую в общем... Мне интересно, чем",CR        DB "может нам помочь такая маленькая"        DB NEXT        DB "хилая старушка?",HERO        DB "Я не старушка, я колдунья!",SOBES        DB "Чо-то Хевор такое говорил...",CR        DB "Но он, кажется, обмолвился, что",CR        DB "колдунья будет в черном плаще,"        DB NEXT        DB "и из рук молнии пускать будет...",HERO        DB "Глупые суеверия!",SOBES        DB "Как вы сказали?.. Ну да ладно.",CR        DB "Выходит, вся надежда на вас...",SCRPT,21ZD3     DB "Как у вас дела, Задолбайло?",SOBES        DB "Кую.",ENDZD4     DB "Извините, вы не подскажете, как",CR        DB "мне пройти через кладбище?",SOBES        DB "Там прорубаться надо... Топором!",CR        DB "Ух, люблю я это дело, только вот",CR        DB "вурдалаков всяких боюсь.",HERO        DB "Так может вы дадите мне свой",CR        DB "топор?",SOBES        DB "Топор нужно еще ковать, а у меня",CR        DB "в горле пересохло. Мне бы",CR        DB "заправиться.",HERO        DB "Эх, кузнец! Ладно, что-нибудь",CR        DB "придумаю. А ты пока куй.",SCRPT,23ZD5     DB "Топор еще не готов?",SOBES        DB "Работа спорится... Но сухо...",ENDZD6     DB "Пивко поможет творческому",CR        DB "процессу?",SOBES        DB "Ох, да! И творческому, и",CR        DB "процессу... и... буль-буль...",CR        DB "Эххх... Ах да! Вот атличнейший"        DB NEXT        DB "тапор! Лови... В смысле держи!",SCRPT,22ZD7     ;DB "Ну, как пиво? Пенное?",SOBES        ;DB "Спасибо, как раз для моей морды!",CR        ;DB "Петро, как всегда, держит марку.",DIALOG,8ZD8     DB "Ты не знаешь как расправиться",CR        DB "со Зловетом?",SOBES        DB "Да я его! Я знаишь какой? Да я",CR        DB "дзесяток Злавретов адной левай",CR        DB "ложу...",DIALOG,3ZD9     DB "Как дела, кузнец?",SOBES        DB "Кую... И пью... Когда я пью,",CR        DB "я кую. Я кую - значит, я пью...",CR        DB "Философия, понимаишь!",ENDZD10    DB "Привет! У тебя случайно тараканы",CR        DB "не водятся?",SOBES        DB "Черти? Навалом! Вон один как раз",CR        DB "на завалинке щас сидит.",HERO        DB "Да не черти! Тараканы... Такие",CR        DB "рыжие, с усами!",SOBES        DB "А, закусь!.. Щазз поймаю... А ты",CR        DB "пока мне курева найди, ладно?",CR        DB "Чертей вроде дымом можно пугнуть!",SCRPT,61;           123456789-123456789-123456789-123ZD11    DB "Вот тебе курево.",SOBES        DB "Спасибо! А я засушил тараканчика.",CR        DB "Держи.",SCRPT,48ZD12    DB "Задолбайло, помогите мне!",SOBES        DB "Тьфу, тьфу, нечистая! Сгинь!",ENDZD13    DB "Возьмите, кузнец!",SOBES        DB "Ну так и знал, что они вернутся!",ENDZEND